pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address deployer) public {
        vm.assume(deployer != address(0));
        vm.prank(deployer);
        RoundFactory c2 = new RoundFactory();
        vm.prank(deployer);
        c2.initialize();
        assertTrue(c2.owner() == deployer);
    }
}
